s=Get-Date -Format "yyyy-MM-dd HH:mm:ss"; $stamp=Get-Date -Format "yyyyMMdd_HHmmss"; Write-Host "[RUNEFORGE_APLICAR_PERMISOS_OPENSSH][$ts]"; $Root="C:\RUNEFOGE_PRO\runeforge"; $AuditDir=Join-Path $Root "data\audits\openssh_acl_fix_$stamp"; $Dir="C:\Program Files\OpenSSH-Win64"; $Config="C:\ProgramData\ssh\sshd_config"; $AdminKeys="C:\ProgramData\ssh\administrators_authorized_keys"; $HostFix=Join-Path $Dir "FixHostFilePermissions.ps1"; $UserFix=Join-Path $Dir "FixUserFilePermissions.ps1"; New-Item -ItemType Directory -Force -Path $AuditDir | Out-Null; $AclBefore=Join-Path $AuditDir "acl_before_$stamp.txt"; $ConfigBak=Join-Path $AuditDir "sshd_config_$stamp.bak"; $KeysBak=Join-Path $AuditDir "administrators_authorized_keys_$stamp.bak"; $Rollback=Join-Path $AuditDir "rollback-openssh-acl-$stamp.ps1"; $Log=Join-Path $AuditDir "openssh_acl_fix_result_$stamp.json"; icacls "C:\ProgramData\ssh" /save $AclBefore /t /c | Out-Null; Copy-Item $Config $ConfigBak -Force; Copy-Item $AdminKeys $KeysBak -Force; Set-Content -LiteralPath $Rollback -Encoding utf8BOM -Value "Set-StrictMode -Version Latest`n`$ErrorActionPreference='Stop'`nStop-Service sshd -Force -ErrorAction SilentlyContinue`nCopy-Item -LiteralPath '$ConfigBak' -Destination '$Config' -Force`nCopy-Item -LiteralPath '$KeysBak' -Destination '$AdminKeys' -Force`nicacls '$AdminKeys' /inheritance:r | Out-Null`nicacls '$AdminKeys' /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null`nicacls '$AdminKeys' /setowner '*S-1-5-32-544' | Out-Null`nStart-Service sshd`nWrite-Host '[OK] Rollback ACL OpenSSH aplicado.'"; $r=[ordered]@{Timestamp=$ts;AuditDir=$AuditDir;HostFixExists=(Test-Path $HostFix);UserFixExists=(Test-Path $UserFix);ConfigBackup=$ConfigBak;KeysBackup=$KeysBak;Rollback=$Rollback;HostFixExit=$null;UserFixExit=$null;AclReinforced=$false;SshdConfigTest=$null;Restarted=$false;Service=$null;Port22=$null;RecentCrashes=$null;Status="STARTED";Error=$null}; try{ if(!(Test-Path $HostFix)){throw "No existe $HostFix"}; if(!(Test-Path $UserFix)){throw "No existe $UserFix"}; powershell.exe -ExecutionPolicy Bypass -File $HostFix -Confirm:$false; $r.HostFixExit=$LASTEXITCODE; powershell.exe -ExecutionPolicy Bypass -File $UserFix -Confirm:$false; $r.UserFixExit=$LASTEXITCODE; icacls $AdminKeys /inheritance:r | Out-Null; icacls $AdminKeys /grant:r "*S-1-5-18:F" "*S-1-5-32-544:F" | Out-Null; icacls $AdminKeys /remove:g "*S-1-1-0" "*S-1-5-11" "*S-1-5-32-545" "$env:USERDOMAIN\$env:USERNAME" 2>$null | Out-Null; icacls $AdminKeys /setowner "*S-1-5-32-544" | Out-Null; $r.AclReinforced=$true; & "$Dir\sshd.exe" -t -f $Config; $r.SshdConfigTest=$LASTEXITCODE; if($LASTEXITCODE -ne 0){throw "sshd_config no pasó validación"}; Restart-Service sshd -Force; Start-Sleep -Seconds 2; $r.Restarted=$true; $svc=Get-Service sshd; $r.Service=$svc.Status.ToString(); $r.Port22=Get-NetTCPConnection -State Listen -LocalPort 22 -ErrorAction SilentlyContinue | Select-Object LocalAddress,LocalPort,OwningProcess; $r.RecentCrashes=Get-WinEvent -FilterHashtable @{LogName="Application";StartTime=(Get-Date).AddMinutes(-3)} -ErrorAction SilentlyContinue | Where-Object {$_.Message -match "sshd.exe|APPCRASH|c0000005"} | Select-Object TimeCreated,ProviderName,Id; if($svc.Status -ne "Running"){throw "sshd no quedó Running"}; $r.Status="OK_OPENSSH_PERMISSIONS_APPLIED"}catch{$r.Status="FAILED";$r.Error=$_.Exception.Message}; $r | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $Log -Encoding utf8; Write-Host "[RUNEFORGE_APLICAR_PERMISOS_OPENSSH_RESULT]"; $r | ConvertTo-Json -Depth 8